# ---- PDF ---------------------------------------------------------------------------------------


def minimal_pdf(pages, extra=b""):
    objs = [b"<< /Type /Catalog /Pages 2 0 R " + extra + b">>"]
    kids = b" ".join(f"{3 + i} 0 R".encode() for i in range(pages))
    objs.append(b"<< /Type /Pages /Count " + str(pages).encode() + b" /Kids [" + kids + b"] >>")
    for _ in range(pages):
        objs.append(b"<< /Type /Page /Parent 2 0 R /MediaBox [0 0 200 200] >>")
    out = io.BytesIO()
    out.write(b"%PDF-1.4\n")
    offsets = []
    for n, body in enumerate(objs, 1):
        offsets.append(out.tell())
        out.write(f"{n} 0 obj\n".encode() + body + b"\nendobj\n")
    xref = out.tell()
    out.write(f"xref\n0 {len(objs) + 1}\n0000000000 65535 f \n".encode())
    for off in offsets:
        out.write(f"{off:010d} 00000 n \n".encode())
    out.write(f"trailer\n<< /Size {len(objs) + 1} /Root 1 0 R >>\nstartxref\n{xref}\n%%EOF\n".encode())
    return out.getvalue()


def test_a_pdf_is_counted_and_its_active_content_is_reported_not_run(tmp_path):
    f = tmp_path / "a.pdf"
    f.write_bytes(minimal_pdf(3, b"/OpenAction << /S /JavaScript /JS (app.alert(1)) >> "))
    code, out, _ = run(f)
    assert code == 0 and out["detected_type"] == "pdf" and out["pdf"]["pages"] == 3
    raw = out["pdf"]["active_content_found_by_raw_scan"]
    assert raw["javascript"] >= 1 and raw["open_action"] == 1
    assert out["pdf"]["encrypted"] is False


def test_an_encrypted_pdf_is_reported_and_not_opened(tmp_path):
    f = tmp_path / "e.pdf"
    f.write_bytes(minimal_pdf(1, b"/Encrypt 9 0 R "))
    code, out, _ = run(f)
    assert code == 0 and out["pdf"]["encrypted"] is True and out["pdf"]["pages"] is None
    assert "Never guess" in out["pdf"]["encrypted_note"]


# ---- what the program itself may do -------------------------------------------------------------


def test_our_code_calls_no_process_and_opens_no_socket():
    source = TOOL.read_text()
    imported = set(re.findall(r"^\s*(?:import|from)\s+([A-Za-z_][A-Za-z0-9_]*)", source, re.M))
    forbidden = {
        "socket", "ssl", "urllib", "http", "ftplib", "smtplib", "requests", "httpx", "asyncio",
        "subprocess", "ctypes", "multiprocessing", "importlib", "pickle", "marshal", "shutil",
    }
    assert imported & forbidden == set()
    assert not re.search(r"(?<![\w.])(eval|exec|compile|__import__)\s*\(|os\.(system|popen)\s*\(", source)
    assert "xml.etree.ElementTree" in source and "lxml" not in source


